INSERT INTO _seed_neuro_ap1_context (unit_id,actor_id) SELECT curricular_unit_id,updated_by FROM quiz_topics WHERE id='quiz-topic-neuro-ap1' AND status='published' AND deleted_at IS NULL LIMIT 1;
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-154',unit_id,'quiz-topic-neuro-ap1','Que vasos deixam sulcos na face interna do frontal e parietais?',NULL,'Podem observar-se buracos inconstantes nos parietais, próximos do sulco sagital e anteriormente à sutura lambdóide, que permitem a passagem de veias emissárias relacionadas com o seio sagital superior. As faces internas do frontal e dos parietais são marcadas por sulcos que alojam os ramos frontal e parietal dos <strong>vasos meníngeos médios</strong>. Nestes sulcos abrem-se pequenos canais para vasos perfurantes destinados à medula hematopoiética do díploe.<p><small>Gray’s Anatomy, 42.ª ed., p. 565.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-154-answer','quiz-neuro-ap1-154','Vasos meníngeos médios',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-154-incorrect','quiz-neuro-ap1-154','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-155',unit_id,'quiz-topic-neuro-ap1','Que sulco mediano aloja o seio sagital superior?',NULL,'As impressões correspondentes às circunvoluções cerebrais são menos nítidas nos ossos da calota do que na base craniana. Na face interna da calota, a crista frontal anteromediana participa na inserção da margem aderente da foice do cérebro e continua-se posteriormente com o <strong>sulco sagital</strong>, que aloja o seio sagital superior. A extremidade anterior estreita da foice fixa-se especificamente à crista galli, como descrito na anatomia das pregas da dura-máter.<p><small>Gray’s Anatomy, 42.ª ed., p. 565.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-155-answer','quiz-neuro-ap1-155','Sulco sagital',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-155-incorrect','quiz-neuro-ap1-155','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-156',unit_id,'quiz-topic-neuro-ap1','Em que estrutura óssea se fixa a extremidade anterior da foice do cérebro?',NULL,'A foice do cérebro é uma lâmina forte, em crescente, situada no plano sagital e interposta na fissura longitudinal entre os hemisférios cerebrais. É estreita anteriormente, onde a sua extremidade se fixa à <strong>crista galli</strong>, e alarga-se posteriormente, onde se continua com a tenda do cerebelo. A sua margem superior convexa prende-se à superfície craniana interna de ambos os lados da linha média até à protuberância occipital interna; o seio sagital superior percorre um sulco craniano no interior da dura-máter ao longo desta margem, e a foice fixa-se aos lábios desse sulco.<p><small>Gray’s Anatomy, 42.ª ed., cap. 25, pp. 398–399.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-156-answer','quiz-neuro-ap1-156','Crista galli',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-156-incorrect','quiz-neuro-ap1-156','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-157',unit_id,'quiz-topic-neuro-ap1','Que depressões junto do sulco sagital alojam granulações aracnoideias?',NULL,'A extremidade anterior estreita da foice fixa-se especificamente à crista galli, como descrito na anatomia das pregas da dura-máter. De ambos os lados do sulco sagital existem depressões irregulares, as <strong>fovéolas granulares</strong>, que se tornam maiores e mais numerosas com a idade e alojam habitualmente granulações aracnoideias.<p><small>Gray’s Anatomy, 42.ª ed., p. 565.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-157-answer','quiz-neuro-ap1-157','Fovéolas granulares',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-157-incorrect','quiz-neuro-ap1-157','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-158',unit_id,'quiz-topic-neuro-ap1','Que seio percorre a margem superior aderente da foice do cérebro?',NULL,'A sua margem superior convexa prende-se à superfície craniana interna de ambos os lados da linha média até à protuberância occipital interna; o <strong>seio sagital superior</strong> percorre um sulco craniano no interior da dura-máter ao longo desta margem, e a foice fixa-se aos lábios desse sulco. A margem inferior é livre e côncava e contém o seio sagital inferior.<p><small>Gray’s Anatomy, 42.ª ed., cap. 25, pp. 398–399.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-158-answer','quiz-neuro-ap1-158','Seio sagital superior',1,1);
