INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-160',unit_id,'quiz-topic-neuro-ap1','Com que prega dural se continua posteriormente a foice do cérebro?',NULL,'A foice do cérebro é uma lâmina forte, em crescente, situada no plano sagital e interposta na fissura longitudinal entre os hemisférios cerebrais. É estreita anteriormente, onde a sua extremidade se fixa à crista galli, e alarga-se posteriormente, onde se continua com a <strong>tenda do cerebelo</strong>. A sua margem superior convexa prende-se à superfície craniana interna de ambos os lados da linha média até à protuberância occipital interna; o seio sagital superior percorre um sulco craniano no interior da dura-máter ao longo desta margem, e a foice fixa-se aos lábios desse sulco.<p><small>Gray’s Anatomy, 42.ª ed., cap. 25, pp. 398–399.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
